var id = (Console.ReadLine() ?? "").Trim();
if (id.Length == 0 || id.Contains(' ')) Environment.Exit(1);
if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var initial) || initial < 0 || initial > 100000) Environment.Exit(1);
var account = new Account(id, initial);
var commands = (Console.ReadLine() ?? "").Split(' ');
foreach (var token in commands)
{
    if (token.Length == 0) Environment.Exit(1);
    var separator = token.IndexOf(':');
    if (separator <= 0) Environment.Exit(1);
    var action = token[..separator];
    if (!int.TryParse(token[(separator + 1)..], out var amount)) Environment.Exit(1);
    if (action == "deposit") account.Deposit(amount);
    else if (action == "withdraw") account.Withdraw(amount);
    else Environment.Exit(1);
}
Console.WriteLine($"account={account.Id} balance={account.Balance}");

sealed class Account
{
    public string Id { get; }
    public int Balance { get; private set; }

    public Account(string id, int initialBalance)
    {
        Id = id;
        Balance = initialBalance;
    }

    public void Deposit(int amount)
    {
        if (amount > 0) Balance += amount;
    }

    public void Withdraw(int amount)
    {
        if (amount > 0 && amount <= Balance) Balance -= amount;
    }
}
